using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Diagnostics;
using System.Globalization;

namespace M3trik.Unitytk.Models.Tests
{
    /// <summary>
    /// A ported model's golden cases, generated by its Python reference at test
    /// time (<c>ptk.Conformance.cases(name, seed, **options)</c>), so a port is
    /// never held to a stale copy, and parsed with the core's JSON reader into the
    /// tree every record is read from. The Python is <c>UNITYTK_PYTHON</c>, else
    /// <c>python</c> on the PATH, and must import pythontk. Every model's tests
    /// share it, so it sits in the project's namespace, not one feature's.
    /// </summary>
    static class Conformance
    {
        const string Script =
            "import json, sys\n" +
            "import pythontk as ptk\n" +
            "options = json.loads(sys.argv[3])\n" +
            "json.dump(ptk.Conformance.cases(sys.argv[1], seed=int(sys.argv[2]), **options), sys.stdout)\n";

        /// <summary>The document of the model <paramref name="name"/>: <c>{"tolerance", "cases", ...}</c>.</summary>
        /// <param name="options">The provider's own sizing, as a JSON object (<c>{"per_rig": 4}</c>).</param>
        /// <exception cref="InvalidOperationException">No Python, or one that cannot generate the cases.</exception>
        public static IDictionary<string, object> Cases(string name, int seed, string options)
        {
            string python = Environment.GetEnvironmentVariable("UNITYTK_PYTHON");
            if (string.IsNullOrEmpty(python)) python = "python";
            var info = new ProcessStartInfo(python)
            {
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
            };
            info.ArgumentList.Add("-c");
            info.ArgumentList.Add(Script);
            info.ArgumentList.Add(name);
            info.ArgumentList.Add(seed.ToString(CultureInfo.InvariantCulture));
            info.ArgumentList.Add(options);
            Process process;
            try
            {
                process = Process.Start(info);
            }
            catch (Win32Exception e)
            {
                throw new InvalidOperationException(
                    $"No Python at '{python}' ({e.Message}): set UNITYTK_PYTHON to a Python that imports pythontk.", e);
            }
            using (process)
            {
                var error = process.StandardError.ReadToEndAsync();
                string output = process.StandardOutput.ReadToEnd();
                process.WaitForExit();
                if (process.ExitCode != 0)
                    throw new InvalidOperationException(
                        $"'{python}' could not generate the {name} cases (exit {process.ExitCode}): " +
                        $"{error.Result.Trim()} -- set UNITYTK_PYTHON to a Python that imports pythontk.");
                return (IDictionary<string, object>)M3trik.Unitytk.Core.Json.Parse(output, false);
            }
        }
    }
}
